  'ที่ปรึกษาฝั่งบัญชีและธุรกิจ': { en: 'Accounting & business advisor', zh: '会计与业务顾问' },
  'พันธมิตรด้านเทคโนโลยีและระบบ (เมื่อเหมาะสม)': { en: 'Technology & systems partner (where appropriate)', zh: '技术与系统合作伙伴（视需要）' },
  'กระบวนการทางบัญชี': { en: 'Accounting processes', zh: '会计流程' },
  'ผังบัญชี (Chart of Accounts)': { en: 'Chart of Accounts', zh: '会计科目表' },
  'การควบคุมภายใน': { en: 'Internal controls', zh: '内部控制' },
  'ข้อกำหนดด้านต้นทุน': { en: 'Costing requirements', zh: '成本核算需求' },
  'ข้อกำหนดด้านรายงาน': { en: 'Reporting requirements', zh: '报表需求' },
