  'คำนวณเงินเดือน รายการหัก และจัดทำสลิปเงินเดือน': { en: 'Payroll and deduction calculation, plus payslips', zh: '计算工资与扣款，并制作工资单' },
  'พื้นฐาน + ยื่นประกันสังคมและภาษีหัก ณ ที่จ่ายจากเงินเดือน และรายงานเงินเดือนรายเดือน': { en: 'Basic, plus social security and payroll withholding tax filing and monthly payroll reports', zh: '基础服务，另含社保及工资预扣税申报与月度薪资报告' },
  'ใบกำกับภาษีขาย': { en: 'Sales tax invoices', zh: '销售税务发票' },
  'ใบกำกับภาษีซื้อ / ใบแจ้งหนี้': { en: 'Purchase tax invoices / bills', zh: '采购税务发票 / 账单' },
  'ใบเสร็จรับเงิน': { en: 'Receipts', zh: '收据' },
  'รายการจ่ายเงิน': { en: 'Payments', zh: '付款' },
