export function translateContent(source: string, locale: Locale): string {
  if (locale === 'th') return source;
  const normalized = source.replace(/\s+/g, ' ').trim();
  const direct = contentTranslations[normalized]?.[locale];
  if (direct) return source.replace(normalized, direct);

  const replacements: Array<[string, string, string]> = [
    ['หน้าหลัก', 'Home', '首页'],
    ['นัดปรึกษาฟรี', 'Free Consultation', '免费咨询'],
    ['ขั้นตอนที่', 'Step', '步骤'],
    ['นาที', 'min read', '分钟'],
    ['ครั้ง/เดือน', 'times/month', '次/月'],
    ['ครั้ง/ไตรมาส', 'time/quarter', '次/季度'],
    ['บาท/เดือน', 'THB/month', '泰铢/月'],
    ['บาท/โครงการ', 'THB/project', '泰铢/项目'],
    ['บาท/ครั้ง', 'THB/engagement', '泰铢/次'],
    ['ม.ค.', 'Jan', '1月'],
    ['ก.พ.', 'Feb', '2月'],
    ['มี.ค.', 'Mar', '3月'],
    ['เม.ย.', 'Apr', '4月'],
    ['พ.ค.', 'May', '5月'],
    ['มิ.ย.', 'Jun', '6月'],
    ['ก.ค.', 'Jul', '7月'],
  ];
  return replacements.reduce(
    (text, [thai, en, zh]) => text.replaceAll(thai, locale === 'en' ? en : zh),
    source,
  );
}

export function isLocale(value: string | null): value is Locale {
  return locales.includes(value as Locale);
}
